        .clk_i(clk_i), .rst_ni(rst_ni), .pe_in_b_i(pe_in_b),
        .sel_b_i(sel_b), .is_signed_b_i(is_signed_b), .zero_i(zero_dp8),
        .b_dp8_o(b_dp8)
    );

    pe_array_sqr pe_array_sqr_i (
        .clk_i(clk_i), .rst_ni(rst_ni),
        .a_dp8_i(a_dp8), .b_dp8_i(b_dp8),
        .neg_i(neg), .sel_shift_i(sel_shift),
        .l0_sum_o(pe_l0_sum), .l0_carry_o(pe_l0_carry),
        .l1_sum_o(pe_l1_sum), .l1_carry_o(pe_l1_carry),
        .l2_sum_o(pe_l2_sum), .l2_carry_o(pe_l2_carry),
        .l3_sum_o(pe_l3_sum), .l3_carry_o(pe_l3_carry)
    );

    pe_array_alpha_sqr pe_array_alpha_sqr_i (
        .clk_i(clk_i), .rst_ni(rst_ni),
        .a_dp8_i(a_dp8), .is_signed_b_i(is_signed_b),
        .neg_i(neg), .sel_shift_i(sel_shift),
        .l0_sum_o(a_l0_sum), .l0_carry_o(a_l0_carry),
        .l1_sum_o(a_l1_sum), .l1_carry_o(a_l1_carry),
        .l2_sum_o(a_l2_sum), .l2_carry_o(a_l2_carry),
        .l3_sum_o(a_l3_sum), .l3_carry_o(a_l3_carry)
    );

    pe_array_beta_sqr pe_array_beta_sqr_i (
        .clk_i(clk_i), .rst_ni(rst_ni),
        .b_dp8_i(b_dp8), .is_signed_a_i(is_signed_a), .zero_i(zero_dp8),
        .neg_i(neg), .sel_shift_i(sel_shift),
        .l0_sum_o(b_l0_sum), .l0_carry_o(b_l0_carry),
        .l1_sum_o(b_l1_sum), .l1_carry_o(b_l1_carry),
        .l2_sum_o(b_l2_sum), .l2_carry_o(b_l2_carry),
        .l3_sum_o(b_l3_sum), .l3_carry_o(b_l3_carry)
    );

    const_sqr const_sqr_i (
        .mode_i(mode_c), .c_o(c_o), .c_neg_o(c_neg_o)
    );

    acc_array_sqr acc_array_sqr_i (
        .clk_i(clk_i), .rst_ni(rst_ni),
        .pe_l0_sum_i(pe_l0_sum), .pe_l0_carry_i(pe_l0_carry),
        .pe_l1_sum_i(pe_l1_sum), .pe_l1_carry_i(pe_l1_carry),
        .pe_l2_sum_i(pe_l2_sum), .pe_l2_carry_i(pe_l2_carry),
        .pe_l3_sum_i(pe_l3_sum), .pe_l3_carry_i(pe_l3_carry),
        .a_l0_sum_i(a_l0_sum), .a_l0_carry_i(a_l0_carry),
        .a_l1_sum_i(a_l1_sum), .a_l1_carry_i(a_l1_carry),
        .a_l2_sum_i(a_l2_sum), .a_l2_carry_i(a_l2_carry),
        .a_l3_sum_i(a_l3_sum), .a_l3_carry_i(a_l3_carry),
        .b_l0_sum_i(b_l0_sum), .b_l0_carry_i(b_l0_carry),
        .b_l1_sum_i(b_l1_sum), .b_l1_carry_i(b_l1_carry),
        .b_l2_sum_i(b_l2_sum), .b_l2_carry_i(b_l2_carry),
        .b_l3_sum_i(b_l3_sum), .b_l3_carry_i(b_l3_carry),
        .c_i(c_o), .c_neg_i(c_neg_o),
        .acc_i(acc_word),
        .sel_out_i(sel_out), .sel_acc_i(sel_acc),
        .sel_const_i(sel_const), .prop_carry_i(prop_carry),
        .pe_out_o(pe_out)
    );

    initial clk_i = 1'b0;
    always #(CLK_HALF) clk_i = ~clk_i;

    function automatic logic signed [15:0] rand_signed(input int width);
        logic [15:0] r;
        int pk;
        r = 16'($urandom);
        pk = $urandom % 5;
        case (width)
            4:       return (pk == 0) ? -16'sd8     : (pk == 1) ? 16'sd7     : 16'($signed(r[3:0]));
            8:       return (pk == 0) ? -16'sd128   : (pk == 1) ? 16'sd127   : 16'($signed(r[7:0]));
            default: return (pk == 0) ? -16'sd32768 : (pk == 1) ? 16'sd32767 : $signed(r);
        endcase
    endfunction

    function automatic logic signed [15:0] rand_signed_sym(input int width);
        int m;
        m = (1 << (width - 1)) - 1;
        return 16'($signed(($urandom % (2*m + 1)) - m));
    endfunction

    task automatic set_controls(input int mi);
        for (int p = 0; p < NUM_PAIR; p++) begin
            sel_a[p] = SEL_A[mi][p];
            sel_b[p] = SEL_B[mi][p];
        end
        for (int i = 0; i < NUM_DP8; i++) begin
            is_signed_a[i] = IS_SIGNED_A[mi][i];
            is_signed_b[i] = IS_SIGNED_B[mi][i];
            zero_dp8[i]    = ZERO_I_LUT[mi][i];
        end
        neg        = NEG_I[mi];
        sel_shift  = SEL_SHIFT[mi];
        sel_out    = 2'(TAP_LEVEL[mi]);
        sel_const  = SEL_CONST[mi];
        mode_c     = 4'(MODE_NUM[mi]);
        prop_carry = (TAP_LEVEL[mi] >= 1);
    endtask

    function automatic longint read_result(input int lvl, input int node);
        int hlane, llane;
        if (lvl == 0) return longint'($signed(pe_out[node]));
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;    end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;             end
        endcase
        return longint'($signed({pe_out[hlane], pe_out[llane]}));
    endfunction

    task automatic rand_matrices(input int mi);
        int M, K, N, PA, PB, cplx;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; PB = MM_DIMS[mi][4]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                A_re[m][k] = rand_signed(PA);
                A_im[m][k] = (cplx != 0) ? rand_signed(PA) : 16'sd0;
            end
        for (int k = 0; k < K; k++)
            for (int n = 0; n < N; n++) begin
                B_re[k][n] = rand_signed(PB);
                B_im[k][n] = (cplx != 0) ? rand_signed_sym(PB) : 16'sd0;
            end
    endtask

    task automatic golden(input int mi);
        int K, NOUT, m, n;
        longint re, im;
        K = MM_DIMS[mi][1]; NOUT = MM_DIMS[mi][6];
        for (int o = 0; o < NOUT; o++) begin
            m = MM_OUT[mi][o][0]; n = MM_OUT[mi][o][1];
            re = 0; im = 0;
            for (int k = 0; k < K; k++) begin
                re = re + longint'(A_re[m][k]) * longint'(B_re[k][n])
                        - longint'(A_im[m][k]) * longint'(B_im[k][n]);
                im = im + longint'(A_re[m][k]) * longint'(B_im[k][n])
                        + longint'(A_im[m][k]) * longint'(B_re[k][n]);
            end
            X_re[o] = re;
            X_im[o] = im;
        end
    endtask

    task automatic pack(input int mi);
        int M, K, N, PA, cplx, pos;
        pe_in_a = '0;
        pe_in_b = '0;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                pos = MM_RE_A[mi][m][k] & 255;
                if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][7:0];
                if (PA == 16) begin
                    pos = (MM_RE_A[mi][m][k] >> 8) & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][15:8];
                end
                if (cplx != 0) begin
                    pos = MM_IM_A[mi][m][k] & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][7:0];
                    if (PA == 16) begin
                        pos = (MM_IM_A[mi][m][k] >> 8) & 255;
                        if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][15:8];
                    end
                end
            end
        if (MODE_NUM[mi] == 12)
            pack_b_c16c16();
        else
            for (int k = 0; k < K; k++)
                for (int n = 0; n < N; n++)
                    for (int p = 0; p < 4; p++) begin
                        pos = (MM_RE_B[mi][k][n] >> (8*p)) & 255;
                        if (pos != 255) pe_in_b[pos*4 +: 4] = B_re[k][n][p*4 +: 4];
                        if (cplx != 0) begin
                            pos = (MM_IM_B[mi][k][n] >> (8*p)) & 255;
                            if (pos != 255) pe_in_b[pos*4 +: 4] = B_im[k][n][p*4 +: 4];
                        end
                    end
    endtask

    task automatic put_b16(input logic [15:0] v, input int blk_hi, input int blk_lo, input int lane);
        pe_in_b[(blk_hi*16 + 8 + lane)*4 +: 4] = v[15:12];
        pe_in_b[(blk_hi*16     + lane)*4 +: 4] = v[11:8];
        pe_in_b[(blk_lo*16 + 8 + lane)*4 +: 4] = v[7:4];
        pe_in_b[(blk_lo*16     + lane)*4 +: 4] = v[3:0];
    endtask

    task automatic pack_b_c16c16;
        for (int k = 0; k < 4; k++) begin
            put_b16( B_re[k][0], 0, 1, k);
            put_b16(-B_im[k][0], 0, 1, 4 + k);
            put_b16( B_im[k][0], 2, 3, k);
            put_b16( B_re[k][0], 2, 3, 4 + k);
        end
    endtask

    task automatic compare(input int mi);
        int NOUT, lvl, rn, in;
        longint r;
        NOUT = MM_DIMS[mi][6]; lvl = TAP_LEVEL[mi];
        for (int o = 0; o < NOUT; o++) begin
            rn = MM_OUT[mi][o][2];
            in = MM_OUT[mi][o][3];
            r = read_result(lvl, rn);
            if (r !== X_re[o]) begin
                err = err + 1;
                $display("mode %0d output %0d Re: golden=%0d dut=%0d", MODE_NUM[mi], o, X_re[o], r);
            end
            if (in >= 0) begin
                r = read_result(lvl, in);
                if (r !== X_im[o]) begin
                    err = err + 1;
                    $display("mode %0d output %0d Im: golden=%0d dut=%0d", MODE_NUM[mi], o, X_im[o], r);
                end
            end
        end
    endtask

    task automatic clear_acc;
        for (int j = 0; j < NUM_LANE; j++) acc_word[j] = '0;
    endtask

    task automatic set_acc(input int lvl, input int node, input longint val);
        int hlane, llane;
        if (lvl == 0) begin
            acc_word[node] = val[ACC_W-1:0];
            return;
        end
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;   end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;            end
        endcase
        acc_word[hlane] = val[2*ACC_W-1:ACC_W];
        acc_word[llane] = val[ACC_W-1:0];
    endtask

    longint acc_seed    [0:MAXO-1];
    longint acc_seed_im [0:MAXO-1];

    initial begin
        int err0, NOUT, lvl, rn, in;
        longint r, gexp;
        $display("\nStarting acc_array_sqr (square path: disp -> pe|alpha|beta -> const -> acc) verification (%0d modes x %0d random)...\n",
                 NUM_MODE, NUM_RAND);
`ifdef VCD
        $dumpfile("activity.vcd");
        $dumpvars(0, tb_acc_array_sqr.acc_array_sqr_i);
`endif

        rst_ni  = 1'b0;
        pe_in_a = '0;
        pe_in_b = '0;
        for (int p = 0; p < NUM_PAIR; p++) begin
            sel_a[p] = '0; sel_b[p] = '0;
        end
        for (int i = 0; i < NUM_DP8; i++) begin
            is_signed_a[i] = 1'b0; is_signed_b[i] = 1'b0; zero_dp8[i] = 1'b0;
        end
        neg = '0; sel_const = '0; mode_c = '0;
        sel_shift = '0; sel_out = '0; sel_acc = 1'b0; prop_carry = 1'b0;
        clear_acc();
        err = 0; npass = 0;
        repeat (3) @(posedge clk_i);
        rst_ni = 1'b1;

        for (int mi = 0; mi < NUM_MODE; mi++) begin
            set_controls(mi);
            clear_acc();
            sel_acc = 1'b0;
            err0 = err;
            for (int t = 0; t < NUM_RAND; t++) begin
                rand_matrices(mi);
                golden(mi);
                pack(mi);
                @(posedge clk_i);
                @(posedge clk_i);
                @(posedge clk_i);
                #(T_SETTLE);
                compare(mi);
            end
            if (err == err0) begin
                npass = npass + 1;
                $display("  mode %0d: PASS", MODE_NUM[mi]);
            end else
                $display("  mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

        $display("\nAccumulation scenario: external seed + %0d feedback iterations...", NUM_ACC);
        for (int mi = 0; mi < NUM_MODE; mi++) begin
            set_controls(mi);
            rand_matrices(mi);
            golden(mi);
            pack(mi);
            NOUT = MM_DIMS[mi][6];
            lvl  = TAP_LEVEL[mi];
            clear_acc();
            for (int o = 0; o < NOUT; o++) begin
                acc_seed[o] = longint'(rand_signed(16));
                set_acc(lvl, MM_OUT[mi][o][2], acc_seed[o]);
                if (MM_OUT[mi][o][3] >= 0) begin
                    acc_seed_im[o] = longint'(rand_signed(16));
                    set_acc(lvl, MM_OUT[mi][o][3], acc_seed_im[o]);
                end
            end
            sel_acc = 1'b0;
            repeat (3) @(posedge clk_i);
            #(T_SETTLE);
            for (int it = 1; it < NUM_ACC; it++) begin
                sel_acc = 1'b1;
                @(posedge clk_i);
            end
            #(T_SETTLE);
            err0 = err;
            for (int o = 0; o < NOUT; o++) begin
                rn = MM_OUT[mi][o][2];
                in = MM_OUT[mi][o][3];
                r    = read_result(lvl, rn);
                gexp = acc_seed[o] + NUM_ACC * X_re[o];
                if (r !== gexp) begin
                    err = err + 1;
                    $display("  acc mode %0d out %0d Re: golden=%0d dut=%0d", MODE_NUM[mi], o, gexp, r);
                end
                if (in >= 0) begin
                    r    = read_result(lvl, in);
                    gexp = acc_seed_im[o] + NUM_ACC * X_im[o];
                    if (r !== gexp) begin
                        err = err + 1;
                        $display("  acc mode %0d out %0d Im: golden=%0d dut=%0d", MODE_NUM[mi], o, gexp, r);
                    end
                end
            end
            if (err == err0)
                $display("  acc mode %0d: PASS", MODE_NUM[mi]);
            else
                $display("  acc mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

`ifdef VCD
        $dumpoff;
`endif
        $display("\nacc_array verification: %0d/%0d single-shot modes passed (%0d total mismatches)\n",
                 npass, NUM_MODE, err);
        $finish;
    end

endmodule
